```javascript
// Function to handle annotation highlighting
function handleAnnotationHighlight(annotation) {
    // Create a tooltip element
    const tooltip = document.createElement('div');
    tooltip.style.position = 'absolute';
    tooltip.style.backgroundColor = 'rgba(0, 0, 0, 0.75)';
    tooltip.style.borderRadius = '5px';
    tooltip.style.padding = '5px';
    tooltip.style.opacity = '0';
    tooltip.style.transition = 'opacity 0.3s ease';

    // Get the annotation details
    const annotationDetails = {
        id: annotation.id,
        text: annotation.text,
        position: {
            x: annotation.position.x,
            y: annotation.position.y
        }
    };

    // Add an event listener to the annotation to show the tooltip when it is hovered over
    annotation.addEventListener('mouseenter', () => {
        tooltip.style.opacity = '1';
        tooltip.textContent = `ID: ${annotation.id}\nText: ${annotation.text}\nPosition: ${annotation.position.x}, ${annotation.position.y}`;
    });

    annotation.addEventListener('mouseleave', () => {
        tooltip.style.opacity = '0';
    });

    // Append the tooltip to the document body
    document.body.appendChild(tooltip);
}

